    const memoMood = detectMood(memo.content);
    if (todayMood === "sad" || todayMood === "angry") {
      if (memoMood === "happy" || memoMood === "touched") moodBonus = 4;
    } else if (todayMood === "happy") {
      if (memoMood === "touched") moodBonus = 2;
    }
    const jitter = Math.random() * 1.5;
