          const lines = memo.content.split("\n");
          const original = lines[lineNum];
          const m = original.match(taskRe);
          if (!m) return;
          const checked = /[xX]/.test(m[2]);
          lines[lineNum] = original.replace(
            taskRe,
            checked ? "$1 $3" : "$1x$3"
          );
